 <body>
   <main class="page-shell">
     <section class="hero-panel" aria-label="Support information">
       <div>
         <div class="eyebrow">Support</div>
         <h1>Reach our team with one clear request.</h1>
         <p>
           Share your contact details and a support specialist will follow up with the right next step
           for your account, billing, or product issue.
         </p>
       </div>

       <ul class="hero-points" aria-label="Support benefits">
         <li><span aria-hidden="true"></span>Fast routing to the right support team</li>
         <li><span aria-hidden="true"></span>Clear follow-up for account and product questions</li>
         <li><span aria-hidden="true"></span>Modern, accessible form experience</li>
       </ul>
     </section>

     <section class="form-panel" aria-labelledby="contact-form-title">
       <h2 id="contact-form-title">Contact support</h2>
       <p class="form-intro">
         Fill in the required details below. Phone number is optional if email is your preferred way to hear back.
       </p>

       <form id="support-form" novalidate>
         <div class="form-field">
           <label for="fullName">Full name</label>
           <input
             id="fullName"
             name="fullName"
             type="text"
             autocomplete="name"
             placeholder="Jordan Lee"
             required
             aria-describedby="fullName-error"
           >
           <p id="fullName-error" class="field-message" hidden></p>
         </div>

         <div class="form-field">
           <label for="email">Email address</label>
           <input
             id="email"
             name="email"
             type="email"
             autocomplete="email"
             placeholder="jordan@example.com"
             required
             aria-describedby="email-error"
           >
           <p id="email-error" class="field-message" hidden></p>
         </div>

         <div class="form-field">
           <label for="phone">Phone number</label>
           <input
             id="phone"
             name="phone"
             type="tel"
             autocomplete="tel"
             inputmode="tel"
             placeholder="(555) 123-4567"
             aria-describedby="phone-helper phone-error"
           >
           <p id="phone-helper" class="helper-text">Optional. Use digits, spaces, parentheses, or dashes, for example: (555) 123-4567 or +1 555 123 4567.</p>
           <p id="phone-error" class="field-message" hidden></p>
         </div>

         <div class="submit-row">
           <button type="submit">Submit request</button>
           <p id="form-status" class="form-status" hidden aria-live="polite"></p>
         </div>
       </form>
     </section>
   </main>

   <script>
     const form = document.getElementById("support-form");
     const statusMessage = document.getElementById("form-status");

     const fields = {
       fullName: {
         input: document.getElementById("fullName"),
         error: document.getElementById("fullName-error"),
         validate(value) {
           if (!value.trim()) {
             return "Full name is required.";
           }
           return "";
         }
       },
       email: {
         input: document.getElementById("email"),
         error: document.getElementById("email-error"),
         validate(value) {
           const trimmed = value.trim();
           if (!trimmed) {
             return "Email address is required.";
           }
           if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(trimmed)) {
             return "Enter a valid email address.";
           }
           return "";
         }
       },
       phone: {
         input: document.getElementById("phone"),
         error: document.getElementById("phone-error"),
         validate(value) {
           const trimmed = value.trim();
           if (!trimmed) {
             return "";
           }
           if (!/^\+?[0-9()\-\s]{7,20}$/.test(trimmed)) {
             return "Enter a valid phone number using digits and common separators.";
           }
           return "";
         }
       }
     };
